use super::*;
use serde_json::{json, Value};
fn scores(analysis: &Analysis, kind: &str) -> Vec<usize> {
    analysis
        .blocks
        .iter()
        .filter(|b| b.kind == kind)
        .map(|b| b.complexity)
        .collect()
}
#[test]
fn installed_radon_601_literal_expectations_cover_decisions_functions_classes_and_closures() {
    // Expectations copied from upstream test data, not generated by this implementation.
    // Full MIT notice is retained alongside the implementation.
    let cases: Value = serde_json::from_str(include_str!(
        "../tests/fixtures/radon_complexity/upstream-6.0.1.json"
    ))
    .unwrap();
    for case in cases.as_array().unwrap() {
        let analysis = analyze_with_options(
            case["source"].as_str().unwrap(),
            "fixture.py",
            Options {
                no_assert: case["no_assert"].as_bool().unwrap(),
            },
        )
        .unwrap_or_else(|e| panic!("{}: {e}", case["case"]));
        if let Some(expected) = case.get("module_complexity") {
            assert_eq!(
                json!(analysis.module_complexity),
                *expected,
                "{}",
                case["case"]
            );
        }
        if let Some(expected) = case.get("function_complexities") {
            assert_eq!(json!(scores(&analysis, "F")), *expected, "{}", case["case"]);
        }
        if let Some(expected) = case.get("class_complexity") {
            assert_eq!(
                json!(scores(&analysis, "C")),
                json!([expected]),
                "{}",
                case["case"]
            );
        }
        if let Some(expected) = case.get("method_complexities") {
            assert_eq!(json!(scores(&analysis, "M")), *expected, "{}", case["case"]);
        }
    }
}
#[test]
fn assertions_do_not_visit_their_boolean_test_or_message_and_with_has_no_increment() {
    let source="async def f():\n    assert a and b, c if d else e\n    with thing: pass\n    async with other: pass\n";
    assert_eq!(scores(&analyze(source, "a.py").unwrap(), "F"), vec![2]);
    assert_eq!(
        scores(
            &analyze_with_options(source, "a.py", Options { no_assert: true }).unwrap(),
            "F"
        ),
        vec![1]
    );
}
#[test]
fn trystar_and_guarded_capture_follow_radons_actual_node_rules() {
    let source="def f():\n    try:\n        pass\n    except* ValueError:\n        pass\n    else:\n        pass\n    finally:\n        pass\n    match value:\n        case 1 if a and b: pass\n        case capture if c or d: pass\n";
    // TryStar is not Radon's Try node: no handler/else increment. Match subtracts
    // one MatchAs(pattern=None), even a named/guarded capture; guards still visit.
    assert_eq!(scores(&analyze(source, "a.py").unwrap(), "F"), vec![4]);
}
#[test]
fn decorators_defaults_annotations_bases_and_nested_blocks_do_not_leak_into_rows() {
    let source="@deco(a and b)\ndef f(x=a if b else c) -> (a or b):\n    def closure():\n        if a: pass\n    class Hidden:\n        def method(self):\n            if b: pass\n    return 0\n\n@deco(a and b)\nclass Outer(base if cond else other):\n    class Inner:\n        def nested(self):\n            if c: pass\n    def method(self):\n        return 0\n";
    let actual = analyze(source, "scope.py").unwrap();
    assert_eq!(
        actual
            .blocks
            .iter()
            .map(|b| (&*b.key, b.kind, b.line, b.complexity))
            .collect::<Vec<_>>(),
        vec![
            ("scope.py::f", "F", 2, 1),
            ("scope.py::Outer", "C", 11, 2),
            ("scope.py::Outer.method", "M", 15, 1)
        ]
    );
}
#[test]
fn definition_keyword_lines_handle_decorators_and_continuations() {
    let source="@decorate\ndef \\\n    first():\n    pass\n\n@decorate\nasync \\\n    def second():\n    pass\n\n@decorate\nclass \\\n    Third:\n    pass\n";
    let actual = analyze(source, "lines.py").unwrap();
    assert_eq!(
        actual.blocks.iter().map(|b| b.line).collect::<Vec<_>>(),
        vec![2, 7, 12]
    );
}
#[test]
fn rank_boundaries_and_duplicate_symbol_keys_preserve_ratcheting_identity() {
    for (score, expected) in [
        (0, "A"),
        (5, "A"),
        (6, "B"),
        (10, "B"),
        (11, "C"),
        (20, "C"),
        (21, "D"),
        (30, "D"),
        (31, "E"),
        (40, "E"),
        (41, "F"),
    ] {
        assert_eq!(rank(score), expected);
    }
    let actual = analyze("def same(): pass\ndef same():\n    if a: pass\n", "dup.py").unwrap();
    assert_eq!(actual.blocks[0].key, actual.blocks[1].key);
    assert_eq!(actual.blocks[0].complexity, 1);
    assert_eq!(actual.blocks[1].complexity, 2);
}
#[test]
fn python312_version_and_resource_admission_refuse_instead_of_emitting_partial_rows() {
    for source in [
        "def broken(:\n",
        "\u{feff}def bom(): pass\n",
        "type Alias[T = int] = T\n",
        "x = t'value'\n",
    ] {
        assert!(analyze(source, "bad.py").is_err(), "{source}");
    }
    assert!(analyze(&"def f(): pass\n".repeat(4097), "many.py").is_err());
    assert!(analyze(
        &" ".repeat(crate::candidate_python::MAX_BYTES + 1),
        "large.py"
    )
    .is_err());
}
#[test]
fn unicode_identifiers_use_cpython_normalized_names() {
    let actual = analyze(
        "def K(): pass\nclass Klass:\n    def Kethod(self): pass\n",
        "unicode.py",
    )
    .unwrap();
    assert_eq!(
        actual
            .blocks
            .iter()
            .map(|b| b.key.as_str())
            .collect::<Vec<_>>(),
        vec![
            "unicode.py::K",
            "unicode.py::Klass",
            "unicode.py::Klass.Kethod"
        ]
    );
}
